const body = $input.first().json.body || $input.first().json;
const binaryData = $input.first().binary || {};

// Extract form fields
const title = (body.title || body.meeting_title || 'Meeting').trim();
const attendees = (body.attendees || '').split(',').map(a => a.trim()).filter(Boolean);
const language = (body.language || 'de').trim().toLowerCase();

// Find the audio file in binary data
const audioKey = Object.keys(binaryData).find(k => {
  const mt = binaryData[k]?.mimeType || '';
  return mt.startsWith('audio/') || mt === 'application/octet-stream';
});

if (!audioKey) {
  return [{ json: { valid: false, error: 'Keine Audiodatei gefunden. Unterstützte Formate: MP3, M4A, WAV, WEBM, OGG.' } }];
}

// n8n binary size check (fileSize in bytes if available)
const fileSize = binaryData[audioKey]?.fileSize || 0;
const maxSize = 25 * 1024 * 1024; // 25 MB Whisper limit
if (fileSize > 0 && fileSize > maxSize) {
  return [{ json: { valid: false, error: `Datei zu groß (${Math.round(fileSize / 1024 / 1024)}MB). Maximum: 25MB.` } }];
}

return [{
  json: {
    valid: true,
    title,
    attendees,
    language,
    audioKey,
    fileName: binaryData[audioKey]?.fileName || 'meeting.mp3',
    mimeType: binaryData[audioKey]?.mimeType || 'audio/mpeg',
    received_at: new Date().toISOString()
  }
}];

const meta = $('Eingabe validieren').first().json;

// Whisper with response_format=text returns plain text body
const transcript = ($input.first().json.body || $input.first().json.data || '').toString().trim();

if (!transcript) {
  throw new Error('Transkription leer – Datei möglicherweise nicht lesbar oder stumm.');
}

return [{
  json: {
    ...meta,
    transcript,
    transcript_length: transcript.length,
    word_count: transcript.split(/\s+/).length
  }
}];

