parameters.jsCode:
const meta = $('Transkript extrahieren').first().json;
const response = $input.first().json;

// Extract tool_use result from Claude's structured output
const toolUse = response.content?.find(c => c.type === 'tool_use');
if (!toolUse) throw new Error('Claude returned no tool_use block');

const data = toolUse.input;
const date = new Date(meta.received_at).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' });
const attendeeList = meta.attendees.length > 0 ? meta.attendees.join(', ') : 'Nicht angegeben';

// Build Markdown document
const lines = [
  `# Meeting: ${meta.title} — ${date}`,
  '',
  `**Teilnehmer:** ${attendeeList}`,
  `**Wortanzahl Transkript:** ${meta.word_count}`,
  '',
  '## Zusammenfassung',
  ...data.summary.map(s => `- ${s}`),
  '',
  '## Entscheidungen',
];

if (data.decisions.length > 0) {
  data.decisions.forEach((d, i) => {
    lines.push(`${i + 1}. ${d.decision}${d.owner ? ` *(${d.owner})*` : ''}`);
  });
} else {
  lines.push('*Keine Entscheidungen protokolliert.*');
}

lines.push('', '## Aufgaben');
if (data.action_items.length > 0) {
  data.action_items.forEach(a => {
    const due = a.due_date ? ` — bis ${a.due_date}` : '';
    const owner = a.owner ? ` *(${a.owner})* ` : ' ';
    lines.push(`- [ ]${owner}${a.task}${due}`);
  });
} else {
  lines.push('*Keine Aufgaben erfasst.*');
}

lines.push('', '## Offene Fragen');
if (data.open_questions.length > 0) {
  data.open_questions.forEach(q => lines.push(`- ${q}`));
} else {
  lines.push('*Keine offenen Fragen.*');
}

if (data.follow_up_date) {
  lines.push('', '## Nächstes Meeting', data.follow_up_date);
}

lines.push('', '---', `*Automatisch erstellt am ${new Date(meta.received_at).toLocaleString('de-DE')} — Meeting-Protokoll Bot*`);

const markdown = lines.join('\n');

return [{
  json: {
    ...meta,
    summary: data.summary,
    decisions: data.decisions,
    action_items: data.action_items,
    open_questions: data.open_questions,
    follow_up_date: data.follow_up_date || null,
    markdown,
    email_subject: `Meeting-Protokoll: ${meta.title} — ${date}`
  }
}];

